using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
public static class SkillSpriteFolderChecks {
 static int count;static void C(bool ok,string text){if(!ok)throw new Exception(text);count++;Debug.Log("FOLDER_PASS "+text);}static Sprite Image(string path){var t=new Texture2D(4,4);t.SetPixels(Enumerable.Repeat(Color.cyan,16).ToArray());t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path);var importer=(TextureImporter)AssetImporter.GetAtPath(path);importer.textureType=TextureImporterType.Sprite;importer.spriteImportMode=SpriteImportMode.Single;importer.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}static void Move(string a,string b){string e=AssetDatabase.MoveAsset(a,b);if(!string.IsNullOrEmpty(e))throw new Exception(e);}static int Hold(TrainingMoveData d,string name)=>d.data.spriteSequence.frames.Single(f=>f.sprite.name==name).holdFrames;
 public static void Run(){count=0;string root="Assets/__SpriteFolderQA_"+Guid.NewGuid().ToString("N");Directory.CreateDirectory(root+"/Sprite");Directory.CreateDirectory(root+"/Quarantine");AssetDatabase.Refresh();TrainingMoveData draft=null;TrainingMoveDataEditor editor=null;try{var asset=ScriptableObject.CreateInstance<TrainingMoveData>();AssetDatabase.CreateAsset(asset,root+"/Data.asset");var raw=new Texture2D(2,2);File.WriteAllBytes(root+"/Sprite/99.png",raw.EncodeToPNG());UnityEngine.Object.DestroyImmediate(raw);AssetDatabase.ImportAsset(root+"/Sprite/99.png");C(AssetDatabase.LoadAssetAtPath<Sprite>(root+"/Sprite/99.png")!=null,"new PNG in skill Sprite imports automatically");Move(root+"/Sprite/99.png",root+"/Quarantine/99.png");var one=Image(root+"/Sprite/1.png");var calibrated=(TextureImporter)AssetImporter.GetAtPath(root+"/Sprite/1.png");calibrated.spritePixelsPerUnit=77;calibrated.SaveAndReimport();C(((TextureImporter)AssetImporter.GetAtPath(root+"/Sprite/1.png")).spritePixelsPerUnit==77,"existing import calibration is preserved");var ten=Image(root+"/Sprite/10.png");var two=Image(root+"/Sprite/2.png");draft=UnityEngine.Object.Instantiate(asset);var images=SkillSpriteFolderSync.Detect(asset);C(string.Join(",",images.Select(x=>x.sprite.name))=="1,2,10","natural numeric initial order");SkillSpriteFolderSync.Sync(asset,draft);C(draft.data.spriteSequence.frames.All(f=>f.holdFrames==1&&!string.IsNullOrEmpty(f.sourceIdentity)),"new images provisional1F with stable IDs");C(SkillSpriteFolderSync.ValidateSelection(asset,draft,out _),"detected-only selection valid");draft.data.spriteSequence.frames[0].holdFrames=3;draft.data.spriteSequence.frames[1].holdFrames=7;draft.data.spriteSequence.frames[2].holdFrames=11;TrainingMoveDataEditor.SaveDraft(asset,draft);C(asset.data.Duration==draft.data.Duration,"sync never changes move timing");editor=(TrainingMoveDataEditor)Editor.CreateEditor(asset);editor.Draft.data.spriteSequence.frames[0].holdFrames=99;editor.ReloadDraft();C(editor.Draft.data.spriteSequence.frames[0].holdFrames==3,"Cancel discards hold changes");Move(root+"/Sprite/2.png",root+"/Sprite/20.png");C(SkillSpriteFolderSync.Changes(asset,SkillSpriteFolderSync.Detect(asset)).Contains("renamed 1"),"rename appears in sync report");SkillSpriteFolderSync.Sync(asset,draft);C(string.Join(",",draft.data.spriteSequence.frames.Select(f=>f.sprite.name))=="1,10,20","rename reorders naturally");C(Hold(draft,"20")==7&&Hold(draft,"10")==11,"holds follow GUID not array position");TrainingMoveDataEditor.SaveDraft(asset,draft);AssetDatabase.ImportAsset(root+"/Sprite/20.png",ImportAssetOptions.ForceUpdate);SkillSpriteFolderSync.Sync(asset,draft);C(Hold(draft,"20")==7,"reimport retains hold");Move(root+"/Sprite/10.png",root+"/Quarantine/10.png");SkillSpriteFolderSync.Sync(asset,draft);C(draft.data.spriteSequence.frames.Length==2,"removed image leaves active list");TrainingMoveDataEditor.SaveDraft(asset,draft);AssetDatabase.ImportAsset(root+"/Data.asset",ImportAssetOptions.ForceUpdate);asset=AssetDatabase.LoadAssetAtPath<TrainingMoveData>(root+"/Data.asset");UnityEngine.Object.DestroyImmediate(draft);draft=UnityEngine.Object.Instantiate(asset);C(draft.data.spriteSequence.rememberedHolds.Any(h=>h.identity==SkillSpriteFolderSync.Identity(ten)&&h.holdFrames==11),"removed hold ledger survives save/reload");Move(root+"/Quarantine/10.png",root+"/Sprite/10.png");SkillSpriteFolderSync.Sync(asset,draft);C(Hold(draft,"10")==11,"restored same GUID recovers remembered hold");Image(root+"/Sprite/3.png");SkillSpriteFolderSync.Sync(asset,draft);C(Hold(draft,"3")==1&&Hold(draft,"20")==7,"new image does not borrow neighboring hold");TrainingMoveDataEditor.SaveDraft(asset,draft);Move(root+"/Sprite/1.png",root+"/Quarantine/old1.png");Image(root+"/Sprite/1.png");SkillSpriteFolderSync.Sync(asset,draft);C(Hold(draft,"1")==1,"same filename new GUID does not inherit old hold");TrainingMoveDataEditor.SaveDraft(asset,draft);Move(root+"/Sprite/1.png",root+"/Quarantine/new1.png");Move(root+"/Quarantine/old1.png",root+"/Sprite/1.png");SkillSpriteFolderSync.Sync(asset,draft);C(Hold(draft,"1")==3,"original identity hold survives replacement");draft.data.spriteSequence.frames[0].sprite=null;C(!SkillSpriteFolderSync.ValidateSelection(asset,draft,out _),"missing serialized reference rejected");SkillSpriteFolderSync.Sync(asset,draft);C(draft.data.spriteSequence.frames[0].sprite!=null&&Hold(draft,"1")==3,"sync restores missing ref from identity");foreach(var image in SkillSpriteFolderSync.Detect(asset))Move(AssetDatabase.GetAssetPath(image.sprite),root+"/Quarantine/empty-"+image.sprite.name+".png");SkillSpriteFolderSync.Sync(asset,draft);C(draft.data.spriteSequence.frames.Length==0&&draft.data.SequenceSpriteAt(0)==null,"empty folder yields legacy fallback");C(SkillSpriteFolderSync.ValidateSelection(asset,draft,out _),"empty sync saves safely");Directory.CreateDirectory(root+"/Other/Sprite");AssetDatabase.Refresh();var other=ScriptableObject.CreateInstance<TrainingMoveData>();AssetDatabase.CreateAsset(other,root+"/Other/Data.asset");Image(root+"/Other/Sprite/01.png");var second=UnityEngine.Object.Instantiate(other);SkillSpriteFolderSync.Sync(other,second);C(second.data.spriteSequence.frames.Length==1,"common service works for another skill path");draft.data.spriteSequence=second.data.spriteSequence;C(!SkillSpriteFolderSync.ValidateSelection(asset,draft,out _),"foreign skill images cannot be saved from UI");UnityEngine.Object.DestroyImmediate(second);Directory.CreateDirectory(root+"/Sprites");AssetDatabase.Refresh();try{SkillSpriteFolderSync.Detect(asset);throw new Exception("Read both folders");}catch(InvalidOperationException){count++;}Debug.Log("SKILL_FOLDER_CHECKS "+count+" passed");var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"-folderReport");if(i>=0)File.WriteAllText(args[i+1],count+" PASS; 0 FAIL; isolated folder assets");}finally{if(editor!=null)UnityEngine.Object.DestroyImmediate(editor);if(draft!=null)UnityEngine.Object.DestroyImmediate(draft);AssetDatabase.DeleteAsset(root);}}
}
